let srfmMaskedInputs=new WeakSet;function inputFieldMasking(a=document){a.querySelectorAll(".srfm-input-input").forEach(a=>{if(!srfmMaskedInputs.has(a)){var e=a.getAttribute("data-srfm-mask");if("none"!==e){var t={clearIncomplete:!0};switch(e){case"(###) ###-####":t.mask="(999) 999-9999";break;case"(##) ####-####":t.mask="(99) 9999-9999";break;case"dd/mm/yyyy":t.alias="datetime",t.inputFormat="dd/mm/yyyy";break;case"hh:mm:ss":t.alias="datetime",t.inputFormat="HH:MM:ss";break;case"dd/mm/yyyy hh:mm:ss":t.alias="datetime",t.inputFormat="dd/mm/yyyy HH:MM:ss";break;case"custom-mask":var s,i=a.getAttribute("data-custom-srfm-mask");i.startsWith("date:")?(s=i.replace(/^date:\s*/,""),t.alias="datetime",t.inputFormat=s):i.startsWith("alias:")?(s=i.replace(/^alias:\s*/,""),t.alias=s):t.mask=i}srfmMaskedInputs.add(a),new Inputmask(t).mask(a)}}})}document.addEventListener("DOMContentLoaded",()=>inputFieldMasking()),document.addEventListener("srfm_form_before_submission",a=>{a.detail?.form&&inputFieldMasking(a.detail.form)}),window.srfmInitializeInputField=inputFieldMasking;